def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.28
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.6
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    affordable_threats = []
    desperate_count = 0
    rich_count = 0

    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 1.5:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                bid = float(bid)
                prev_bids.append(bid)
                aff = min(float(opp.get('budget', 0)), bid + 8.0)
                affordable_threats.append(aff)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_affordable = max(affordable_threats) if affordable_threats else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_pressure = max(0.0, min(1.0, supply_pressure))

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2

    if no_water_days >= 2:
        urgency += 0.9
    elif no_water_days >= 1:
        urgency += 0.45

    urgency += 0.35 * supply_pressure
    urgency += 0.08 * desperate_count

    if day >= 8:
        urgency += 0.15

    if rich_count == 0:
        urgency -= 0.1

    urgency = max(0.0, min(1.4, urgency))

    if urgency >= 1.0:
        target = max(DAILY_SALARY * 1.08, highest_affordable + 2.5)
    elif urgency >= 0.65:
        target = max(DAILY_SALARY * 0.82, highest_prev + 2.0, highest_affordable * 0.92)
    elif urgency >= 0.35:
        target = max(DAILY_SALARY * 0.56, highest_prev * 0.72)
    else:
        target = DAILY_SALARY * (0.26 + 0.14 * supply_pressure)

    if highest_prev >= 150 and hp > 4 and no_water_days == 0:
        target = min(target, DAILY_SALARY * 0.32)

    if budget < DAILY_SALARY * 0.9:
        target = min(target, budget)
    elif budget < DAILY_SALARY * 1.5 and urgency < 0.65:
        target = min(target, DAILY_SALARY * 0.58)

    if hp <= 2 or no_water_days >= 2:
        target = max(target, min(budget, DAILY_SALARY * 0.95))

    bid = max(0.0, min(float(budget), float(target)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no active opponents, bid low to conserve budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    # Collect yesterday's bids from active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Default bid if no strong signals or for initial rounds
    default_bid = DAILY_SALARY * 0.55

    # Adjust bid based on my HP
    if my_status['hp'] <= 2:
        # Critical HP, bid very aggressively to survive
        return min(my_status['budget'], DAILY_SALARY * 0.95)
    elif my_status['hp'] <= 4:
        # Low HP, bid aggressively
        default_bid = DAILY_SALARY * 0.8

    # Adjust bid further based on opponents' previous bids
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            # Opponents are bidding very high, need to compete strongly
            if my_status['hp'] > 4:
                # Healthy HP, try to win by slightly exceeding, but don't overspend if not critical
                return min(my_status['budget'], max(default_bid, highest_prev_bid + 5))
            else:
                # My HP is already low (3 or 4), must win this round
                return min(my_status['budget'], highest_prev_bid + 10)

        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            # Opponents are bidding moderately, try to win by slightly exceeding
            return min(my_status['budget'], max(default_bid, highest_prev_bid + 2))

        else:
            # Opponents are bidding low, maintain a moderate bid or slightly above them
            return min(my_status['budget'], max(default_bid, highest_prev_bid + 1))

    # If no previous bids from opponents, or no specific condition met, use the calculated default bid
    return min(my_status['budget'], default_bid)
